const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (!entry.isIntersecting) return
    entry.target.style.opacity = "1"
    if (entry.target.style.transform.includes("translate")) entry.target.style.transform = "none"
    revealObserver.unobserve(entry.target)
  })
}, { threshold: 0.05 })

document.querySelectorAll("[style*='opacity:0'], [style*='opacity: 0']").forEach((element) => revealObserver.observe(element))

const navToggle = document.querySelector("#nav-toggle")
const navMenu = document.querySelector("#nav-menu")
const showButton = document.querySelector("#show-button")
const hideButton = document.querySelector("#hide-button")

navToggle?.addEventListener("change", () => {
  navMenu?.classList.toggle("hidden", !navToggle.checked)
  showButton?.classList.toggle("hidden", navToggle.checked)
  hideButton?.classList.toggle("hidden", !navToggle.checked)
})

navMenu?.querySelectorAll("a").forEach((link) => {
  link.addEventListener("click", () => {
    if (navToggle) navToggle.checked = false
  })
})

document.querySelectorAll("main .cursor-pointer").forEach((trigger) => {
  const heading = trigger.querySelector("h3")
  const answer = heading ? faqAnswers[heading.textContent.trim()] : null
  if (!answer) return
  trigger.addEventListener("click", () => {
    const card = trigger.parentElement
    const openPanel = card.querySelector(":scope > .overflow-hidden")
    document.querySelectorAll("main [data-faq-panel]").forEach((panel) => {
      if (panel !== openPanel) panel.remove()
    })
    if (openPanel) {
      openPanel.remove()
      return
    }
    const panel = document.createElement("div")
    panel.className = "overflow-hidden"
    panel.dataset.faqPanel = "true"
    panel.innerHTML = `<div class="pt-4 md:w-4/5"><p class="text-lg">${answer}</p></div>`
    card.append(panel)
  })
})

document.querySelectorAll("button").forEach((button) => {
  const label = button.textContent.trim().toLowerCase()
  if (label !== "monthly" && label !== "yearly") return
  button.addEventListener("click", () => {
    const wrapper = button.parentElement
    const buttons = [...wrapper.querySelectorAll("button")]
    buttons.forEach((item) => {
      item.classList.toggle("text-text-dark", item === button)
      item.classList.toggle("text-white", item !== button)
    })
    const marker = wrapper.querySelector(":scope > div")
    if (marker) marker.style.transform = label === "yearly" ? "translateX(100%)" : "none"
    const section = wrapper.closest("section")
    section?.querySelectorAll("h4.text-h1").forEach((price) => {
      const monthly = Number(price.textContent.replace(/[^0-9.]/g, ""))
      price.dataset.monthly ||= monthly.toFixed(2)
      const value = label === "yearly" ? Number(price.dataset.monthly) * 10 : Number(price.dataset.monthly)
      price.textContent = `$${value.toFixed(2)}`
      const cadence = price.nextElementSibling
      if (cadence) cadence.textContent = label === "yearly" ? "Per User year" : "Per User month"
    })
  })
})

document.querySelectorAll(".accordion-header").forEach((button) => {
  button.addEventListener("click", () => {
    const accordion = button.closest(".accordion")
    accordion?.parentElement?.querySelectorAll(".accordion.active").forEach((item) => {
      if (item !== accordion) item.classList.remove("active")
    })
    accordion?.classList.toggle("active")
  })
})

document.querySelectorAll(".tab").forEach((tab) => {
  const controls = [...tab.querySelectorAll(".tab-nav-item")]
  const panels = [...tab.querySelectorAll(".tab-content")]
  controls.forEach((control, index) => {
    control.addEventListener("click", () => {
      controls.forEach((item, itemIndex) => {
        item.classList.toggle("active", itemIndex === index)
        item.tabIndex = itemIndex === index ? 0 : -1
      })
      panels.forEach((panel, panelIndex) => {
        panel.classList.toggle("block", panelIndex === index)
        panel.classList.toggle("hidden", panelIndex !== index)
      })
    })
  })
})

document.querySelectorAll("button").forEach((button) => {
  const label = button.textContent.trim()
  const step = processSteps[label]
  if (!step) return
  button.addEventListener("click", () => {
    const section = button.closest("section")
    const panel = section?.querySelector(".grid.lg\\:grid-cols-2")
    if (!panel) return
    section.querySelectorAll("button").forEach((item) => {
      const active = item === button
      item.classList.toggle("text-text-dark", active)
      item.classList.toggle("text-white", !active)
      item.classList.toggle("bg-transparent", !active)
      item.querySelector(":scope > div")?.remove()
      if (active) item.insertAdjacentHTML("beforeend", '<div class="absolute inset-0 bg-primary rounded-full" style="opacity: 1;"></div>')
    })
    const heading = panel.querySelector("h3")
    const description = heading?.nextElementSibling
    if (heading) heading.innerHTML = `<strong>${step[0]}</strong><br><em>${step[1]}</em>`
    if (description) description.textContent = step[2]
  })
})

document.querySelectorAll("form").forEach((form) => {
  form.addEventListener("submit", (event) => event.preventDefault())
})

document.querySelectorAll("lite-youtube").forEach((player) => {
  player.style.display = "block"
  player.style.aspectRatio = "16 / 9"
})
